async function resilientFetch(url,options={},config={}){const retries=config.retries??2,timeoutMs=config.timeoutMs??15000;for(let attempt=0;;attempt++){try{const response=await fetch(url,{...options,signal:options.signal||AbortSignal.timeout(timeoutMs)});if((response.status===429||response.status>=500)&&attempt<retries)throw Object.assign(new Error(`HTTP ${response.status}`),{retryable:true});return response}catch(error){if(attempt>=retries||options.signal?.aborted)throw error;config.onRetry?.(attempt+1,error);await new Promise(resolve=>setTimeout(resolve,500*2**attempt))}}}
function beginAgentTransition({title='Agent 正在工作',description='正在安全调用研究工具，请稍候…',steps=[],startedAt,onCancel}={}){const root=$('#agentTransition'),id=++transitionSequence,parsedStart=Date.parse(startedAt||'');activeTransition=id;clearInterval(transitionTimer);transitionStartedAt=Number.isFinite(parsedStart)?Math.min(parsedStart,Date.now()):Date.now();transitionCancelAction=typeof onCancel==='function'?onCancel:null;transitionCancel.hidden=!transitionCancelAction;transitionCancel.disabled=false;transitionCancel.textContent='取消任务';root.className='agent-transition';root.hidden=false;$('#transitionTitle').textContent=title;$('#transitionDescription').textContent=description;$('#transitionElapsed').textContent=String(Math.max(0,Math.floor((Date.now()-transitionStartedAt)/1000)));$('#transitionSteps').innerHTML=steps.map((label,index)=>`<li class="${index===0?'current':''}">${esc(label)}</li>`).join('');const bar=$('#transitionProgress');bar.className='indeterminate';bar.style.width='';$('#transitionMinimize').textContent='继续浏览';requestAnimationFrame(()=>root.classList.add('show'));transitionTimer=setInterval(()=>{if(activeTransition===id)$('#transitionElapsed').textContent=String(Math.max(0,Math.floor((Date.now()-transitionStartedAt)/1000)))},1000);return id}
function updateAgentTransition(id,{index,description,progress}={}){if(id!==activeTransition)return;if(description)$('#transitionDescription').textContent=description;if(Number.isInteger(index))$$('#transitionSteps li').forEach((item,i)=>item.className=i<index?'done':i===index?'current':'');if(Number.isFinite(progress)){const bar=$('#transitionProgress');bar.className='';bar.style.width=`${Math.max(4,Math.min(100,progress))}%`}}
function endAgentTransition(id,{success=true,message,cancelled=false}={}){if(id!==activeTransition)return;clearInterval(transitionTimer);transitionCancelAction=null;transitionCancel.hidden=true;const root=$('#agentTransition');root.classList.remove('minimized');root.classList.add(success?'success':'failed');$('#transitionTitle').textContent=cancelled?'任务已取消':success?'处理完成':'处理未完成';if(message)$('#transitionDescription').textContent=message;const bar=$('#transitionProgress');bar.className='';bar.style.width=cancelled?bar.style.width:'100%';$$('#transitionSteps li').forEach(item=>{if(success)item.className='done'});setTimeout(()=>{if(activeTransition!==id)return;root.classList.remove('show');setTimeout(()=>{if(activeTransition===id){root.hidden=true;activeTransition=0}},280)},success?650:1400)}
$('#transitionMinimize').onclick=()=>{const root=$('#agentTransition'),minimized=root.classList.toggle('minimized');$('#transitionMinimize').textContent=minimized?'展开':'继续浏览'};
