function renderCodebooks(){if(!activeProject?.candidateSelections?.length)return;$('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>官方代码本证据</h4><button id="reviewCodebooks">读取所选文件代码本</button><div id="codebookResults">${(activeProject.codebookReviews||[]).map(r=>`<details><summary>${esc(r.variable)} · ${esc(r.cycle)} · ${esc(r.status)}</summary><p>${esc(r.warning||r.error)}</p><p>${esc(r.url)}</p><small>${esc(r.retrievedAt)} · SHA-256 ${esc(r.sha256)}</small><pre style="white-space:pre-wrap">${esc(r.excerpt)}</pre>${r.fields?`<p>单位：${esc(r.fields.unit||'待核对')}；适用人群：${esc(r.fields.target||'待核对')}</p><p>代码本缺失类取值：${esc(r.fields.missingCodes.map(x=>`${x.code}: ${x.description}`).join('；')||'未提取到')}</p><small>按原文提取，尚未批准清洗规则。</small>`:''}</details>`).join('')}</div></section>`);$('#reviewCodebooks').onclick=async()=>{const b=$('#reviewCodebooks'),transitionId=beginAgentTransition({title:'正在核验官方代码本',description:'Agent 正在读取 CDC 页面并提取变量定义',steps:['读取官方页面','定位变量定义','提取缺失码与单位','生成证据摘要']});b.disabled=true;try{updateAgentTransition(transitionId,{index:1,progress:28});const response=await fetch(`/api/projects/${activeProject.id}/codebook-review`,{method:'POST'});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'读取失败');updateAgentTransition(transitionId,{index:3,progress:90,description:`已完成 ${data.codebookReviews?.length||0} 条代码本证据核验`});syncProject(data);tab('variables');endAgentTransition(transitionId,{message:'官方代码本证据已提取并写入审计记录'})}catch(e){endAgentTransition(transitionId,{success:false,message:e.message});$('#codebookResults').textContent=e.message;b.disabled=false}}}
function renderCleaningApproval(){if(!activeProject?.codebookReviews?.some(x=>x.variableFound))return;const approved=activeProject.cleaningApproval;$('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>清洗规则确认</h4>${approved?`<div class="check">✓ 已确认 ${esc(approved.ruleCount)} 条规则 · ${esc(approved.approvedAt)}</div>`:`<button id="loadCleaningDraft">查看待确认清洗规则</button><div id="cleaningApproval"></div>`}</section>`);const load=$('#loadCleaningDraft');if(!load)return;load.onclick=async()=>{load.disabled=true;try{const response=await fetch(`/api/projects/${activeProject.id}/cleaning-draft`),draft=await response.json();if(!response.ok)throw new Error(draft.error?.message||'规则读取失败');const target=$('#cleaningApproval');target.innerHTML=`${draft.blockers.length?`<div class="warning">${draft.blockers.map(esc).join('<br>')}</div>`:''}<p>规则摘要：<code>${esc(draft.digest)}</code></p><table class="table"><thead><tr><th>变量</th><th>文件/周期</th><th>缺失码</th><th>单位</th></tr></thead><tbody>${draft.rules.map(rule=>`<tr><td>${esc(rule.variable)}</td><td>${esc(rule.file)} · ${esc(rule.cycle)}</td><td>${esc(rule.missingCodes.join('、')||'SAS 缺失值')}</td><td>${esc(rule.unit||'待确认')}</td></tr>`).join('')}</tbody></table><label><input type="checkbox" id="ackMapping"> 我已核对变量与研究概念匹配</label><label><input type="checkbox" id="ackMissing"> 我已核对缺失码</label><label><input type="checkbox" id="ackUnit"> 我已核对单位和适用人群</label><button id="approveCleaning" ${draft.blockers.length?'disabled':''}>确认清洗规则</button><p id="cleaningMessage"></p>`;$('#approveCleaning').onclick=async()=>{const button=$('#approveCleaning');button.disabled=true;try{const result=await fetch(`/api/projects/${activeProject.id}/cleaning-approval`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:'researcher',digest:draft.digest,acknowledgements:{mapping:$('#ackMapping').checked,missingCodes:$('#ackMissing').checked,unitAndPopulation:$('#ackUnit').checked}})}),project=await result.json();if(!result.ok)throw new Error(project.error?.message||'确认失败');syncProject(project);tab('variables');toast('清洗规则已确认并写入审计记录')}catch(error){$('#cleaningMessage').textContent=error.message;button.disabled=false}}}catch(error){$('#cleaningApproval').textContent=error.message;load.disabled=false}}}
function renderModelSpec(){const project=activeProject;if(!project?.cleaningApproval)return;const spec=project.modelSpec;if(spec){$('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>统计模型已冻结</h4><div class="check">✓ ${esc(spec.outcomeFamily)} 结局 · 暴露转换 ${esc(spec.exposureTransform)} · ${esc(spec.covariates.length)} 个协变量</div><small>配置摘要：${esc(spec.digest)}。已生成 model.R，可在研究方案最终确认后进入受控通用执行。</small></section>`);return}const variables=project.variables||[],cycles=project.intent?.cycles||[],approved=role=>variables.filter(x=>x.role===role&&x.confirmationStatus==='codebook_and_cleaning_approved'),cycleChoices=(role,label)=>cycles.map((cycle,index)=>{const items=approved(role).filter(x=>x.cycles?.includes(cycle));return `<label>${esc(cycle)} ${label}<select data-model-${role}="${index}">${items.map(x=>`<option value="${esc(x.variable)}">${esc(x.variable)} · ${esc(x.sourceFile)}</option>`).join('')}</select></label>`}).join(''),weights=variables.filter(x=>x.role==='design'&&/^WT/.test(x.variable)&&cycles.every(c=>x.cycles?.includes(c))),covariates=approved('covariate').filter(x=>cycles.every(c=>x.cycles?.includes(c)));$('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>冻结统计模型</h4><p>逐周期确认模型字段和编码后，Agent 才会生成通用 survey 模型代码。</p>${cycleChoices('exposure','暴露')}${cycleChoices('outcome','结局')}<label>结局类型<select id="modelFamily"><option value="continuous">连续型</option><option value="binary">二分类</option></select></label><label>暴露转换<select id="modelExposureTransform"><option value="raw">原值</option><option value="log2">log2</option><option value="per_sd">每 1 个标准差</option></select></label><label>结局转换<select id="modelOutcomeTransform"><option value="raw">原值</option><option value="threshold_ge">大于等于阈值</option><option value="threshold_eq">等于指定值</option></select></label><label>结局阈值<input id="modelThreshold" type="number" step="any" placeholder="仅阈值转换时必填"></label><label>最低年龄<input id="modelAgeMin" type="number" min="0" max="85" value="${esc(project.intent?.population?.ageMin??18)}"></label><label>分析权重<select id="modelWeight">${weights.map(x=>`<option value="${esc(x.variable)}">${esc(x.variable)}</option>`).join('')}</select></label>${covariates.length?`<fieldset><legend>已核验协变量</legend>${covariates.map((x,index)=>`<label><input type="checkbox" data-model-covariate="${index}"> ${esc(x.variable)} <select data-model-encoding="${index}"><option value="continuous">连续</option><option value="factor">分类</option></select></label>`).join('')}</fieldset>`:'<p><small>当前没有覆盖全部周期且完成代码本/清洗确认的协变量；可先生成未调整模型。</small></p>'}<label><input type="checkbox" id="modelAssociationOnly"> 我确认 NHANES 横断面结果只解释为关联，不作因果结论</label><button id="approveModelSpec" class="primary" ${!weights.length?'disabled':''}>确认并冻结模型</button><p id="modelMessage"></p></section>`);const button=$('#approveModelSpec');if(!button)return;button.onclick=async()=>{button.disabled=true;try{const exposureByCycle={},outcomeByCycle={};cycles.forEach((cycle,index)=>{exposureByCycle[cycle]=$(`[data-model-exposure="${index}"]`).value;outcomeByCycle[cycle]=$(`[data-model-outcome="${index}"]`).value});const selectedCovariates=covariates.flatMap((x,index)=>$(`[data-model-covariate="${index}"]`).checked?[{variable:x.variable,encoding:$(`[data-model-encoding="${index}"]`).value}]:[]),response=await fetch(`/api/projects/${project.id}/model-spec`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:'researcher',outcomeFamily:$('#modelFamily').value,exposureTransform:$('#modelExposureTransform').value,outcomeTransform:$('#modelOutcomeTransform').value,outcomeThreshold:$('#modelThreshold').value,populationAgeMin:$('#modelAgeMin').value,weightVariable:$('#modelWeight').value,covariates:selectedCovariates,exposureByCycle,outcomeByCycle,acknowledgeAssociationOnly:$('#modelAssociationOnly').checked})}),data=await response.json();if(!response.ok)throw new Error(data.error?.message||'模型确认失败');syncProject(data);tab('variables');toast('统计模型已冻结并写入审计记录')}catch(error){$('#modelMessage').textContent=error.message;button.disabled=false}}}
function renderModelSpecV2(){
  const project=activeProject;if(!project?.cleaningApproval)return;const spec=project.modelSpec;let advice=project.weightAdvice;
  if(spec){$('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>统计模型已冻结</h4><div class="check">✓ ${esc(spec.outcomeFamily)} 结局 · 暴露转换 ${esc(spec.exposureTransform)} · ${esc(spec.covariates.length)} 个协变量</div><p>权重策略：<code>${esc(spec.weightPolicy?.formula||spec.weightVariable)}</code> · 分析域 ${esc(spec.weightPolicy?.analysisDomain||'历史配置')}</p><p>子总体方差：${spec.surveyDomainPlan?.defineDesignBeforeDomainSubset?'先定义完整抽样设计，再用 survey subset 进入分析域':'历史配置未记录'}</p><p>缺失数据：${esc(spec.missingDataPolicy?.strategy||'历史配置未记录')} · Table 1：${spec.descriptivePlan?.weighted?'复杂抽样加权并保留未加权 n':'历史配置未记录'}</p><p>敏感性分析：${(spec.sensitivityPlan||[]).map(x=>esc(x.label)).join('；')||'历史配置未预设'}</p><small>配置摘要：${esc(spec.digest)}。可在研究方案最终确认后进入受控通用执行。</small></section>`);return}
  const variables=project.variables||[],cycles=project.intent?.cycles||[],approved=role=>variables.filter(x=>x.role===role&&x.confirmationStatus==='codebook_and_cleaning_approved');
  const cycleChoices=(role,label)=>cycles.map((cycle,index)=>{const items=approved(role).filter(x=>x.cycles?.includes(cycle));return `<label>${esc(cycle)} ${label}<select data-model-${role}="${index}">${items.map(x=>`<option value="${esc(x.variable)}">${esc(x.variable)} · ${esc(x.sourceFile)}</option>`).join('')}</select></label>`}).join('');
  const weights=variables.filter(x=>x.role==='design'&&/^WT/.test(x.variable)&&cycles.every(c=>x.cycles?.includes(c))),concepts=[...new Set(approved('covariate').map(x=>x.concept))],covariates=concepts.map(concept=>({concept,items:approved('covariate').filter(x=>x.concept===concept)})).filter(group=>cycles.every(cycle=>group.items.some(x=>x.cycles?.includes(cycle))));
  const covariateHtml=covariates.map((group,index)=>`<fieldset><legend><label><input type="checkbox" data-model-covariate="${index}"> ${esc(group.concept)}</label></legend><label>编码<select data-model-encoding="${index}"><option value="continuous">连续</option><option value="factor">分类</option></select></label>${cycles.map((cycle,cycleIndex)=>{const items=group.items.filter(x=>x.cycles?.includes(cycle));return `<label>${esc(cycle)}<select data-model-cov-map="${index}-${cycleIndex}">${items.map(x=>`<option value="${esc(x.variable)}">${esc(x.variable)} · ${esc(x.sourceFile)}</option>`).join('')}</select></label>`}).join('')}</fieldset>`).join('');
  const missingCore=cycles.some(cycle=>!approved('exposure').some(x=>x.cycles?.includes(cycle))||!approved('outcome').some(x=>x.cycles?.includes(cycle)));
  const adviceBody=value=>value?`<b>${value.status==='blocked'?'!':'✓'}　Agent 权重建议：</b>${esc(value.formula||'无法自动推荐')}；${esc(value.rationale)}${value.cautions?.length?`<br>${value.cautions.map(x=>`• ${esc(x)}`).join('<br>')}`:''}${value.blockers?.length?`<br>${value.blockers.map(x=>`• ${esc(x)}`).join('<br>')}`:''}`:'正在计算权重建议…';
  const adviceHtml=`<div id="weightAdviceBox" class="${advice?.status==='blocked'?'warning':'check'}">${adviceBody(advice)}</div>`;
  $('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>冻结统计模型</h4><p>逐周期确认模型字段和编码后，Agent 才会生成并执行通用 survey 模型。</p>${cycleChoices('exposure','暴露')}${cycleChoices('outcome','结局')}<label>结局类型<select id="modelFamily"><option value="continuous">连续型</option><option value="binary">二分类</option></select></label><label>暴露转换<select id="modelExposureTransform"><option value="raw">原值</option><option value="log2">log2</option><option value="per_sd">每 1 个标准差</option></select></label><label>结局转换<select id="modelOutcomeTransform"><option value="raw">原值</option><option value="threshold_ge">大于等于阈值</option><option value="threshold_eq">等于指定值</option></select></label><label>结局阈值<input id="modelThreshold" type="number" step="any" placeholder="仅阈值转换时必填"></label><label>最低年龄<input id="modelAgeMin" type="number" min="0" max="85" value="${esc(project.intent?.population?.ageMin??18)}"></label>${adviceHtml}<label>分析权重<select id="modelWeight">${weights.map(x=>`<option value="${esc(x.variable)}" ${x.variable===advice?.recommendedWeight?'selected':''}>${esc(x.variable)}</option>`).join('')}</select></label><label>偏离推荐权重的依据（仅改选时填写）<input id="modelWeightOverride" maxlength="500" placeholder="至少10字，并引用对应组件代码本"></label>${covariateHtml||'<p><small>当前没有覆盖全部周期且完成代码本/清洗确认的协变量；可先生成未调整模型。</small></p>'}<label>缺失数据策略<select id="modelMissingStrategy"><option value="complete_case">完整案例分析，并输出逐变量缺失诊断</option></select></label><p>执行器将自动运行同一完整案例样本的未调整模型，以及权重第1–99百分位截尾敏感性分析。</p><label><input type="checkbox" id="modelAssociationOnly"> 我确认 NHANES 横断面结果只解释为关联，不作因果结论</label><button id="approveModelSpec" class="primary" ${!weights.length||missingCore||advice?.status==='blocked'?'disabled':''}>确认并冻结模型</button><p id="modelMessage"></p></section>`);
  $('#modelWeight').closest('label').insertAdjacentHTML('afterend','<label><input type="checkbox" id="modelWeightAck"> 我已核对最小分析子样本、组件代码本和权重适用范围</label>');
  const button=$('#approveModelSpec');if(!button)return;
  const refreshWeightAdvice=async()=>{const selectedConcepts=covariates.flatMap((group,index)=>$(`[data-model-covariate="${index}"]`).checked?[group.concept]:[]),target=$('#weightAdviceBox');try{const response=await fetch(`/api/projects/${project.id}/weight-advice`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({selectedConcepts})}),value=await response.json();if(!response.ok)throw new Error(value.error?.message||'权重建议更新失败');advice=value;target.className=value.status==='blocked'?'warning':'check';target.innerHTML=adviceBody(value);const recommended=$(`#modelWeight option[value="${value.recommendedWeight}"]`);if(recommended)$('#modelWeight').value=value.recommendedWeight;button.disabled=!weights.length||missingCore||value.status==='blocked'}catch(error){target.className='warning';target.textContent=error.message;button.disabled=true}};
  $$('[data-model-covariate]').forEach(element=>element.addEventListener('change',refreshWeightAdvice));
  button.onclick=async()=>{button.disabled=true;try{
    const exposureByCycle={},outcomeByCycle={};cycles.forEach((cycle,index)=>{exposureByCycle[cycle]=$(`[data-model-exposure="${index}"]`).value;outcomeByCycle[cycle]=$(`[data-model-outcome="${index}"]`).value});
    const selectedCovariates=covariates.flatMap((group,index)=>{if(!$(`[data-model-covariate="${index}"]`).checked)return[];const byCycle={};cycles.forEach((cycle,cycleIndex)=>byCycle[cycle]=$(`[data-model-cov-map="${index}-${cycleIndex}"]`).value);return[{concept:group.concept,encoding:$(`[data-model-encoding="${index}"]`).value,byCycle}]});
    const payload={actor:'researcher',outcomeFamily:$('#modelFamily').value,exposureTransform:$('#modelExposureTransform').value,outcomeTransform:$('#modelOutcomeTransform').value,outcomeThreshold:$('#modelThreshold').value,populationAgeMin:$('#modelAgeMin').value,weightVariable:$('#modelWeight').value,weightOverrideReason:$('#modelWeightOverride').value,missingDataStrategy:$('#modelMissingStrategy').value,covariates:selectedCovariates,exposureByCycle,outcomeByCycle,acknowledgeAssociationOnly:$('#modelAssociationOnly').checked,acknowledgeWeightChoice:$('#modelWeightAck').checked};
    const response=await fetch(`/api/projects/${project.id}/model-spec`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error?.message||'模型确认失败');syncProject(data);tab('variables');toast('统计模型已冻结并写入审计记录');
  }catch(error){$('#modelMessage').textContent=error.message;button.disabled=false}};
}
function renderCandidateSelection(){const project=activeProject;if(!project)return;const candidates=(project.variableDiscovery?.candidates||[]).flatMap(group=>group.items.map(item=>({...item,role:group.role,concept:group.concept})));if(!candidates.length)return;const history=(project.candidateSelections||[]).map(x=>`<p>${esc(x.role)} · ${esc(x.concept||'')} · ${esc(x.variable)} · ${esc(x.file)}：${esc(x.reason)}（待代码本核验）</p>`).join('');$('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>记录候选选择</h4>${history}<select id="candidateChoice">${candidates.map((x,i)=>`<option value="${i}">${esc(x.role)} · ${esc(x.concept)} · ${esc(x.variable)} · ${esc(x.file)}</option>`).join('')}</select><input id="candidateReason" maxlength="1000" placeholder="选择理由；此操作不代表代码本已核验"><button id="saveCandidate" ${project.status!=='awaiting_approval'?'disabled':''}>保存候选选择</button><p id="candidateMessage"></p></section>`);$('#saveCandidate').onclick=async()=>{const button=$('#saveCandidate');button.disabled=true;try{const item=candidates[Number($('#candidateChoice').value)];const response=await fetch(`/api/projects/${project.id}/candidate-selection`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:item.role,concept:item.concept,variable:item.variable,file:item.file,reason:$('#candidateReason').value})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'保存失败');syncProject(data);tab('variables');toast('已保存，下一步核对逐周期代码本')}catch(error){$('#candidateMessage').textContent=error.message;button.disabled=false}}}
function renderCandidateSelectionV2(){
  const project=activeProject;if(!project)return;const discovery=project.variableDiscovery||{},coverage=discovery.coverage,groups=discovery.candidates||[],candidates=groups.flatMap(group=>group.items.map(item=>({...item,role:group.role,concept:group.concept})));if(!candidates.length)return;
  const fallback=[];for(const group of groups)for(const cycle of project.intent?.cycles||[]){const item=group.items.find(value=>value.matchedCycles?.includes(cycle));if(item)fallback.push({...item,role:group.role,concept:group.concept})}
  const sourceRecommendations=coverage?.recommendations?.length?coverage.recommendations:fallback,uniqueRecommendations=[...new Map(sourceRecommendations.map(x=>[`${x.role}:${x.concept}:${x.file}:${x.variable}`,x])).values()],history=(project.candidateSelections||[]).map(x=>`<p>${esc(x.role)} · ${esc(x.concept||'')} · ${esc(x.variable)} · ${esc(x.file)} · ${(x.cycles||[]).map(esc).join('、')}：${esc(x.reason)}（待代码本核验）</p>`).join(''),coreComplete=coverage?coverage.summary?.coreComplete!==false:true,autoReady=coverage?coverage.summary?.autoSelectionReady!==false:coreComplete;
  $('#tabContent').insertAdjacentHTML('beforeend',`<section class="card"><h4>确认 Agent 推荐候选</h4>${history}<p>Agent 已按概念和周期生成 ${uniqueRecommendations.length} 项首选建议。确认只会冻结候选并进入官方代码本核验，不会直接执行分析。</p>${!coreComplete?'<div class="warning">暴露或结局存在周期缺口。请先调整周期、研究概念或手动补充官方候选。</div>':!autoReady?'<div class="warning">核心变量存在弱匹配或并列候选，已关闭一键采用。请在下方手动选择并说明理由。</div>':''}<label><input type="checkbox" id="ackRecommendations"> 我已查看候选变量、说明和目录匹配强度，理解匹配分不是正确率</label>${coverage?'<label><input type="checkbox" id="ackCycleCompatibility"> 我已查看跨周期变量变化、限制条件和缺口，后续仍将核对逐周期代码本</label>':''}<button id="saveRecommendations" class="primary" ${project.status!=='awaiting_approval'||!uniqueRecommendations.length||!autoReady?'disabled':''}>采用 ${uniqueRecommendations.length} 项推荐</button><details><summary>手动改选单个候选</summary><select id="candidateChoice">${candidates.map((x,i)=>`<option value="${i}">${esc(x.role)} · ${esc(x.concept)} · ${esc(x.variable)} · ${esc(x.file)}</option>`).join('')}</select><input id="candidateReason" maxlength="1000" placeholder="说明手动选择理由"><button id="saveCandidate" ${project.status!=='awaiting_approval'?'disabled':''}>保存单项</button></details><p id="candidateMessage"></p></section>`);
  const save=async(items,payload,button)=>{button.disabled=true;try{const response=await fetch(`/api/projects/${project.id}/candidate-selection`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error?.message||'保存失败');syncProject(data);tab('variables');toast(`已保存 ${items.length} 项候选，下一步核验代码本`)}catch(error){$('#candidateMessage').textContent=error.message;button.disabled=false}};
  $('#saveRecommendations').onclick=()=>{const items=uniqueRecommendations.map(item=>({role:item.role,concept:item.concept,variable:item.variable,file:item.file,reason:'研究者采用 Agent 基于 CDC 官方目录说明和周期覆盖矩阵的首选建议'}));save(items,{acknowledgeRecommendations:$('#ackRecommendations').checked,acknowledgeCrossCycleReview:coverage?$('#ackCycleCompatibility').checked:true,coverageDigest:discovery.coverageDigest,items},$('#saveRecommendations'))};
  $('#saveCandidate').onclick=()=>{const item=candidates[Number($('#candidateChoice').value)],payload={role:item.role,concept:item.concept,variable:item.variable,file:item.file,reason:$('#candidateReason').value};save([item],payload,$('#saveCandidate'))};
}
function renderDiscoveryCandidates(){
  const discovery=activeProject?.variableDiscovery;if(!discovery)return;const groups=discovery.candidates||[],coverage=discovery.coverage,label={exposure:'暴露',outcome:'结局',covariate:'协变量'},strength={strong:'强',moderate:'中等',weak:'弱'},issue={cycle_gap:'存在周期缺口',weak_catalog_match:'存在弱目录匹配',ambiguous_top_matches:'首选与备选匹配分并列',variable_name_changes:'跨周期变量名变化',eligibility_constraints_present:'目录含适用条件',cross_cycle_codebook_review_required:'必须逐周期核对代码本'};
  const summary=coverage?`<section class="card"><h4>变量覆盖与兼容性总览</h4><div class="${coverage.summary.autoSelectionReady?'check':'warning'}"><b>${coverage.summary.autoSelectionReady?'✓':'!'}　</b>核心变量覆盖：${esc(coverage.summary.coveredCells)}/${esc(coverage.summary.totalCells)} 个概念—周期单元；缺口 ${esc(coverage.summary.missingCells)}；弱匹配 ${esc(coverage.summary.weakCells)}；并列候选 ${esc(coverage.summary.ambiguousCells||0)}</div><p>${coverage.warnings.length?coverage.warnings.map(x=>`• ${esc(issue[x]||x)}`).join('<br>'):'未发现目录级覆盖缺口；仍须核对代码本、单位、缺失码和测量方法。'}</p><small>来源：${esc(discovery.source)} · ${esc(discovery.retrievedAt)} · 覆盖摘要 ${esc(discovery.coverageDigest?.slice(0,16))}</small></section>`:'';
  const matrix=coverage?.groups?.map(group=>`<section class="card"><h4>${esc(label[group.role]||group.role)}：${esc(group.concept)} <span class="badge">${esc(group.coveredCycles)}/${esc(group.totalCycles)} 周期</span></h4>${group.issues.length?`<p><small>${group.issues.map(x=>esc(issue[x]||x)).join('；')}</small></p>`:''}<table class="table"><thead><tr><th>周期</th><th>首选候选</th><th>官方说明</th><th>匹配强度</th><th>备选/限制</th></tr></thead><tbody>${group.cells.map(cell=>cell.preferred?`<tr><td>${esc(cell.cycle)}</td><td><code>${esc(cell.preferred.variable)}</code><br><small>${esc(cell.preferred.file)}</small></td><td>${esc(cell.preferred.description)}</td><td>${esc(strength[cell.preferred.matchStrength]||cell.preferred.matchStrength)} · ${esc(cell.preferred.score.toFixed(2))}</td><td>${cell.alternatives.length?`备选：${cell.alternatives.map(x=>`<code>${esc(x.variable)}</code>`).join('、')}<br>`:''}${esc(cell.preferred.constraints||'无目录限制；仍需代码本确认')}</td></tr>`:`<tr><td>${esc(cell.cycle)}</td><td colspan="4"><span class="warning">未找到该周期候选</span></td></tr>`).join('')}</tbody></table><details><summary>查看该概念全部目录候选</summary>${groups.find(x=>x.role===group.role&&x.concept===group.concept)?.items?.length?`<table class="table"><thead><tr><th>变量</th><th>说明</th><th>文件</th><th>周期</th><th>匹配分</th></tr></thead><tbody>${groups.find(x=>x.role===group.role&&x.concept===group.concept).items.map(item=>`<tr><td><code>${esc(item.variable)}</code></td><td>${esc(item.description)}</td><td>${esc(item.file)}</td><td>${esc(item.matchedCycles?.join('、')||'待核对')}</td><td>${esc(Number(item.score||0).toFixed(2))}</td></tr>`).join('')}</tbody></table>`:'没有候选'}</details></section>`).join('');
  const fallback=!coverage?groups.map(group=>`<section class="card"><h4>${esc(label[group.role]||group.role)}：${esc(group.concept)}</h4><small>目录候选尚未确认，不能直接用于分析。</small>${group.items.length?`<table class="table"><thead><tr><th>变量</th><th>说明</th><th>文件</th><th>匹配周期</th></tr></thead><tbody>${group.items.map(item=>`<tr><td>${esc(item.variable)}</td><td>${esc(item.description)}</td><td>${esc(item.file)}</td><td>${esc(item.matchedCycles?.join('、')||'待核对')}</td></tr>`).join('')}</tbody></table>`:'<p>未找到候选，请调整概念或检查检索错误。</p>'}</section>`).join(''):'';
  $('#tabContent').insertAdjacentHTML('afterbegin',`${(discovery.errors||[]).map(error=>`<div class="warning">目录查询未完成：${esc(error)}</div>`).join('')}${summary}${matrix||fallback||''}`)
}
function logs(project){const tasks=project?.agentPlan?.tasks;if(tasks?.length){const labels={interpret_question:'解析研究问题',discover_variables:'发现 NHANES 变量',review_evidence:'检索和评估文献',design_analysis:'制定统计方案',approve_protocol:'研究者确认',generate_and_execute:'生成并执行分析',quality_and_report:'质量检查与报告'};$('#logs').innerHTML=tasks.map(task=>`<div class="log"><span>${task.status==='completed'?'✓':task.status==='blocked'?'!':'✦'}</span><div><b>${esc(labels[task.id]||task.id)}</b><p>${esc(task.agent)} · ${esc(task.status)}</p><small>${esc(task.output)}</small></div></div>`).join('');return}$('#logs').innerHTML='<div class="log"><span>✦</span><div><b>等待 Agent 启动</b><p>提交研究问题后自动编排任务</p></div></div>'}
function toast(x){$('#toast').textContent=x;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2000)}
$$('[data-example]').forEach(b=>b.onclick=()=>$('#question').value=b.dataset.example);$$('[data-add]').forEach(b=>b.onclick=()=>$('#question').value+=($('#question').value?'；':'')+b.dataset.add);$$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
let activeProject=null,eventSource=null,lastPubMedData=null;
const statusLabels={draft:'草稿',running:'处理中',awaiting_approval:'待确认',approved:'已确认'};
function stageIndex(project){if(project.status==='approved')return 5;return Math.max(0,['parse','variables','literature','protocol','analysis','quality','report'].indexOf(project.stage))}
function syncProject(project){activeProject=project;const intent=project.intent||{},population=intent.population||{},cycles=intent.cycles||[],feasibility=project.feasibility,statusText={executable:'可执行真实分析',design_only:'仅支持方案设计',needs_clarification:'需要补充研究问题'}[feasibility?.status]||'可行性评估中';$('#studyTitle').textContent=project.title||'未命名研究';$('#headerProjectTitle').textContent=project.title||'未命名研究';$('#studyCycle').textContent=`ACTIVE STUDY · NHANES ${cycles.length?`${cycles[0]} 至 ${cycles.at(-1)}`:'周期待确认'}`;$('#studyPopulation').textContent=`美国 ${population.ageMin?`${population.ageMin} 岁以上`:'年龄待确认'}人群 · 复杂抽样横断面研究`;const ambiguity=(intent.ambiguities||[]).map(x=>`• ${esc(x)}`).join('<br>')||'自动识别已完成，仍需研究者确认。',feasibilityText=feasibility?`<br><b>可行性：${esc(statusText)}</b><br>${esc(feasibility.message)}${feasibility.blockers?.length?`<br>${feasibility.blockers.map(x=>`• ${esc(x)}`).join('<br>')}`:''}`:'';$('#researcherWarning').innerHTML=`<b>!　研究者确认点</b><br>${project.status==='approved'?'研究方案已确认。':ambiguity}${feasibilityText}${project.agentPlan?.nextAction?`<br><b>下一步：</b>${esc(project.agentPlan.nextAction)}`:''}`;$('#continue').textContent=project.status==='approved'?'研究方案已确认 ✓':'确认研究方案 →';$('#continue').disabled=project.status==='approved';tabs.design=designTab(project);tabs.variables=variablesTab(project);tabs.literature=literatureTab(project);tabs.code=analysisTab('code');tabs.qc=analysisTab('qc');pipeline(stageIndex(project));logs(project);tab(project.status==='approved'?'qc':'design');$$('.recent-project').forEach(x=>x.classList.toggle('selected',x.dataset.projectId===project.id))}
async function loadRecentProjects(){const container=$('#recentProjects');try{const response=await fetch('/api/projects?limit=10'),data=await response.json();if(!response.ok)throw new Error('项目列表加载失败');container.innerHTML=data.items.length?data.items.map(project=>`<button class="recent-project" data-project-id="${esc(project.id)}" title="${esc(project.title||project.question)}">${esc(project.title||'未命名研究')}<span>${esc(statusLabels[project.status]||project.status)} · ${new Date(project.createdAt).toLocaleDateString('zh-CN')}</span></button>`).join(''):'<small>还没有保存的研究</small>';$$('.recent-project').forEach(button=>button.onclick=()=>resumeProject(button.dataset.projectId))}catch{container.innerHTML='<small>暂时无法加载项目</small>'}}
async function resumeProject(projectId){try{eventSource?.close();const response=await fetch(`/api/projects/${projectId}`),project=await response.json();if(!response.ok)throw new Error(project.error?.message||'项目加载失败');syncProject(project);$('#start').classList.add('hidden');$('#results').classList.remove('hidden');window.scrollTo(0,0);toast('已恢复保存的研究')}catch(error){toast(error.message)}}
function designTab(project){const i=project.intent||{},p=i.population||{},cov=i.covariates||[],e=project.evidence?.summary||project.literature?.summary,protocol=project.protocol||{},screened=Boolean(project.evidence?.summary);const evidence=e?`<div class="card wide"><label>${screened?'已筛选证据':'自动方法摘要 · 尚未人工筛选'}</label><p>${screened?`纳入 ${esc(e.included)} 篇 · 排除 ${esc(e.excluded)} 篇 · 待定 ${esc(e.uncertain)} 篇`:`候选文献 ${esc(e.total)} 篇`}</p><div class="tags">${Object.entries(e.methodCounts||{}).map(([x,n])=>`<span>${esc(x)} × ${esc(n)}</span>`).join('')}</div><ol>${(e.recommendations||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><small>${esc(e.warning)}</small></div>`:'',methodPlan=project.protocol?`<div class="card wide"><label>证据驱动统计方案</label><p><b>${esc(protocol.design)}</b> · ${esc(protocol.estimand)}</p><p>主模型：${esc(protocol.primaryModel)}<br>合并权重：${esc(protocol.weight)}</p><ol>${(protocol.secondary||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><small>证据状态：${esc(protocol.evidenceStatus)}；横断面结果不得作因果解释。</small></div>`:'';return `<div class="title"><h3>研究问题结构化结果</h3><span class="confidence">${esc(i.parser?.mode||'解析中')}</span></div><div class="design"><div class="card"><label>暴露</label><p><b>${esc(i.exposure?.label||'待识别')}</b><br>置信度 ${Math.round((i.exposure?.confidence||0)*100)}%</p></div><div class="card"><label>结局</label><p><b>${esc(i.outcome?.label||'待识别')}</b><br>置信度 ${Math.round((i.outcome?.confidence||0)*100)}%</p></div><div class="card"><label>目标人群</label><p>美国 ${p.ageMin?`${esc(p.ageMin)} 岁以上`:'年龄待确认'}；妊娠状态：${esc(p.pregnancy||'待确认')}</p></div><div class="card"><label>NHANES 周期</label><p>${(i.cycles||[]).map(esc).join('、')||'待确认'}</p></div><div class="card wide"><label>候选协变量</label><div class="tags">${cov.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>${evidence}${methodPlan}<div class="card wide"><label>原始研究问题</label><p>${esc(project.question)}</p></div></div>`}
function variablesTab(project){const i=project.intent||{},component=i.exposure?.component||'Laboratory',cycle=i.cycles?.at(-1)||'2017-2018';const mapped=(project.variables||rows.map(r=>({role:r[0],concept:r[1],variable:r[2],source:r[3],transform:r[4]})));return `<div class="title"><h3>NHANES 变量映射</h3><span class="confidence">CDC/NCHS 官方目录</span></div><div class="catalog-search"><select id="cdcComponent">${['Laboratory','Questionnaire','Dietary','Examination','Demographics'].map(x=>`<option ${x===component?'selected':''}>${x}</option>`).join('')}</select><input id="cdcCycle" value="${esc(cycle)}" aria-label="NHANES 周期"><input id="cdcQuery" value="${esc(i.exposure?.label||'')}" placeholder="变量名或概念"><button id="cdcSearch" class="primary">搜索官方变量</button></div><div id="cdcResults" class="catalog-results"><small>点击“搜索官方变量”查询 CDC 实时目录；结果必须由研究者确认。</small></div><div class="card wide"><label>所选周期数据文件覆盖</label><p>验证映射所需的 CDC 官方 XPT 文件是否真实可下载，并检查 SAS XPT 文件签名。</p><button id="verifyVariableCoverage" class="primary">自动验证全部周期</button><div id="variableCoverage"><small>尚未验证。文件通过不等于变量定义已经确认，仍需复核逐周期代码本。</small></div></div><table class="table"><thead><tr><th>角色</th><th>概念</th><th>变量</th><th>文件</th><th>处理</th></tr></thead><tbody>${mapped.map(r=>`<tr><td><span class="badge">${esc(r.role)}</span></td><td>${esc(r.concept)}</td><td><code>${esc(r.variable)}</code></td><td>${esc(r.source)}</td><td>${esc(r.transform)}</td></tr>`).join('')}</tbody></table>`}
function bindCatalogSearch(){const button=$('#cdcSearch');if(!button)return;button.onclick=async()=>{button.disabled=true;button.textContent='查询中…';const transitionId=beginAgentTransition({title:'正在查询 CDC 变量目录',description:'Agent 正在匹配官方数据集、变量名和周期',steps:['构建目录查询','读取 CDC 目录','匹配变量','整理候选']});try{updateAgentTransition(transitionId,{index:1,progress:25});const params=new URLSearchParams({component:$('#cdcComponent').value,cycle:$('#cdcCycle').value,q:$('#cdcQuery').value,limit:'20'}),response=await fetch(`/api/catalog/cdc?${params}`),data=await response.json();if(!response.ok)throw new Error(data.error?.message||'CDC 查询失败');updateAgentTransition(transitionId,{index:3,progress:90,description:`已匹配 ${data.totalMatched||0} 个官方变量`});$('#cdcResults').innerHTML=data.items.length?`<table class="table"><thead><tr><th>变量</th><th>说明</th><th>文件</th><th>周期</th></tr></thead><tbody>${data.items.map(x=>`<tr><td><code>${esc(x.variable)}</code></td><td>${esc(x.description)}</td><td>${esc(x.file)}</td><td>${esc(x.beginYear)}–${esc(x.endYear)}</td></tr>`).join('')}</tbody></table><small>来源：${esc(data.source)} · ${esc(data.totalMatched)} 个匹配结果</small>`:'<p>没有找到匹配变量，请更换英文关键词或周期。</p>';endAgentTransition(transitionId,{message:`CDC 官方变量查询完成，共匹配 ${data.totalMatched||0} 项`})}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});$('#cdcResults').innerHTML=`<p>${esc(error.message)}</p>`}finally{button.disabled=false;button.textContent='搜索官方变量'}}}
function bindVariableCoverage(){const button=$('#verifyVariableCoverage');if(!button)return;button.onclick=async()=>{button.disabled=true;button.textContent='正在逐周期验证…';const target=$('#variableCoverage'),transitionId=beginAgentTransition({title:'正在验证 NHANES 周期覆盖',description:'Agent 正在逐个访问 CDC 官方 XPT 文件',steps:['生成文件清单','检查下载地址','验证 XPT 签名','汇总周期覆盖']});try{updateAgentTransition(transitionId,{index:1,progress:24});const response=await fetch(`/api/projects/${activeProject.id}/data-manifest-validate`,{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.error?.message||'覆盖验证失败');const sources=[...new Set(data.files.map(x=>x.component))],cycles=data.cycles||[];updateAgentTransition(transitionId,{index:3,progress:92,description:`已验证 ${data.summary.valid}/${data.summary.total} 个官方文件`});target.innerHTML=`<div class="${data.summary.invalid?'warning':'check'}"><b>${data.summary.invalid?'!':'✓'}　</b>官方文件 ${esc(data.summary.valid)}/${esc(data.summary.total)} 有效 · 总计 ${(data.summary.totalBytes/1024/1024).toFixed(1)} MB</div><table class="table"><thead><tr><th>文件组件</th>${cycles.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${sources.map(source=>`<tr><td><code>${esc(source)}</code></td>${cycles.map(cycle=>{const file=data.files.find(x=>x.component===source&&x.cycle===cycle);return `<td title="${esc(file?.code||'缺失')}">${file?.valid?'✓ 可用':'! 不可用'}</td>`}).join('')}</tr>`).join('')}</tbody></table><small>来源：CDC/NCHS。此处验证文件可用性、签名和大小；变量单位、缺失码、适用人群及实验室方法变化仍须在代码本中确认。</small>`;endAgentTransition(transitionId,{success:!data.summary.invalid,message:data.summary.invalid?`${data.summary.invalid} 个文件未通过验证`:'全部周期的官方文件均通过验证'})}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});target.innerHTML=`<div class="warning">${esc(error.message)}</div>`}finally{button.disabled=false;button.textContent='重新验证全部周期'}}}
function literatureTab(project){const i=project.intent||{};return `<div class="title"><h3>PubMed 文献证据</h3><span class="confidence">NCBI E-utilities · 实时</span></div><div class="catalog-search"><input id="pubExposure" value="${esc(i.exposure?.term||'')}" placeholder="Exposure"><input id="pubOutcome" value="${esc(i.outcome?.term||'')}" placeholder="Outcome"><select id="pubMode"><option value="expanded" selected>扩展检索</option><option value="precise">精准检索</option></select><select id="pubLimit"><option>5</option><option selected>10</option><option>20</option></select><button id="pubSearch" class="primary">检索 PubMed</button></div><div id="pubResults"><p>扩展检索会使用同义词与 MeSH；精准检索只使用主要术语。结果按题名和摘要相关性排序。</p></div>`}
function renderPubMedData(data,automatic=false){lastPubMedData=data;const articles=Array.isArray(data.articles)?data.articles:[],notice=data.warning?`<div class="warning">${esc(data.warning)}</div>`:data.compliance?.contactEmailConfigured?'':'<div class="warning">当前服务器尚未配置 NCBI 联系邮箱；低频检索可以工作，正式公开服务前应配置。</div>';$('#pubResults').innerHTML=`${notice}<div class="paper"><b>${automatic?'Agent 自动检索式':'检索式'}</b><p>${esc(data.query)}</p><small>${esc(data.source||'NCBI PubMed E-utilities')} · 共 ${esc(data.count||articles.length)} 条，显示 ${articles.length} 条</small></div>${articles.map(a=>`<article class="paper"><h4><a href="${esc(a.url)}" target="_blank" rel="noopener">${esc(a.title)}</a></h4><p>${esc(a.journal)} · ${esc(a.published)} · PMID ${esc(a.pmid)} · <b>相关性 ${esc(a.relevance?.score||0)}/100</b></p><div class="tags">${(a.publicationTypes||[]).map(x=>`<span>${esc(x)}</span>`).join('')}${(a.methods?.tags||[]).map(x=>`<span>方法推断：${esc(x)}</span>`).join('')}${(a.relevance?.signals||[]).map(x=>`<span>命中：${esc(x.label)}</span>`).join('')}</div><p>${esc(a.abstract||'PubMed 未提供摘要。')}</p><small>${esc(a.methods?.basis||'')}；${esc(a.relevance?.basis||'')}</small><div class="screening"><select data-screen="${esc(a.pmid)}"><option value="include" ${a.relevance?.score>=70?'selected':''}>纳入</option><option value="exclude">排除</option><option value="uncertain" ${a.relevance?.score<70?'selected':''}>待定</option></select><input data-reason="${esc(a.pmid)}" placeholder="筛选理由（可选）"></div></article>`).join('')}${articles.length?'<button id="saveEvidence" class="primary">保存证据表并更新研究方案</button>':'<p>没有获得可供筛选的真实文献，可调整关键词后重新检索。</p>'}`;bindEvidenceSave()}
function bindPubMedSearch(){const button=$('#pubSearch');if(!button)return;if(activeProject?.literature)renderPubMedData(activeProject.literature,true);button.onclick=async()=>{button.disabled=true;button.textContent='检索中…';const transitionId=beginAgentTransition({title:'正在检索 PubMed',description:'Agent 正在调用 NCBI，匹配题名、摘要和研究方法',steps:['构建检索式','查询 NCBI','相关性排序','整理方法']});try{updateAgentTransition(transitionId,{index:1,progress:25});const response=await fetch('/api/tools/pubmed/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({exposure:$('#pubExposure').value,outcome:$('#pubOutcome').value,nhanesOnly:true,mode:$('#pubMode').value,limit:$('#pubLimit').value})}),data=await response.json();if(!response.ok)throw new Error(data.error?.message||'PubMed 检索失败');updateAgentTransition(transitionId,{index:3,progress:86,description:`已找到 ${data.articles?.length||0} 篇候选文献，正在整理`});renderPubMedData(data);endAgentTransition(transitionId,{message:`PubMed 检索完成，共整理 ${data.articles?.length||0} 篇候选文献`})}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});$('#pubResults').innerHTML=`<div class="warning">${esc(error.message)}</div>`}finally{button.disabled=false;button.textContent='检索 PubMed'}}}
function bindEvidenceSave(){const button=$('#saveEvidence');if(!button||!lastPubMedData||!activeProject)return;button.onclick=async()=>{button.disabled=true;try{const items=lastPubMedData.articles.map(a=>({pmid:a.pmid,title:a.title,journal:a.journal,published:a.published,relevanceScore:a.relevance?.score,publicationTypes:a.publicationTypes,methodTags:a.methods?.tags,decision:$(`[data-screen="${a.pmid}"]`).value,reason:$(`[data-reason="${a.pmid}"]`).value}));const response=await fetch(`/api/projects/${activeProject.id}/evidence`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:lastPubMedData.query,retrievedAt:lastPubMedData.retrievedAt,items})}),project=await response.json();if(!response.ok)throw new Error(project.error?.message||'保存证据失败');syncProject(project);toast(`证据表已保存：纳入 ${project.evidence.summary.included} 篇`)}catch(error){toast(error.message)}finally{button.disabled=false}}}
function analysisTab(kind){return `<div class="title"><h3>${kind==='code'?'可复现 R 分析项目':'执行前质量检查'}</h3><span class="confidence">冻结配置 · SHA-256 清单</span></div><div id="analysisPackage"><p>正在根据当前项目生成分析包…</p></div>`}
async function bindAnalysisPackage(kind){const container=$('#analysisPackage');if(!container||!activeProject)return;try{const response=await fetch(`/api/projects/${activeProject.id}/analysis-package`),artifact=await response.json();if(!response.ok)throw new Error(artifact.error?.message||'生成分析包失败');const blockers=artifact.readiness.errors.length?`<div class="warning"><b>不可执行：</b><br>${artifact.readiness.errors.map(x=>`• ${esc(x)}`).join('<br>')}</div>`:'<div class="check"><b>✓　</b>准备度检查通过；可交给 Agent 自动完成数据、分析、质量检查和报告。</div>';const content=kind==='code'?`<pre class="code">${esc(artifact.files['analysis.R'])}</pre>`:`${blockers}<pre class="code">${esc(artifact.files['qc-rules.csv'])}</pre>`;container.innerHTML=`${kind==='code'?blockers:''}<p><button id="runFullExecution" class="primary">✦ Agent 自动执行全流程</button> <a href="/api/projects/${activeProject.id}/analysis-package-download">下载 .tar.gz 分析项目</a></p><div id="fullExecution"></div><details><summary>手动调试操作</summary><p><button id="validateDataFiles">验证 CDC 官方 XPT 文件</button> <button id="cacheDataFiles">下载到服务器缓存</button> <button id="runRAnalysis">执行受控 R 分析</button></p></details><div id="dataValidation"></div><div id="dataCache"></div><div id="analysisRun"></div>${content}<small>已冻结通用模型或原有 LBXVIDMS—PHQ-9 模板可进入受控执行；Agent 任务串行运行，最长 20 分钟。</small>`;bindFullExecution();bindDataValidation();bindDataCache();bindAnalysisRun()}catch(error){container.innerHTML=`<div class="warning">${esc(error.message)}</div>`}}
function renderFullExecution(job){const target=$('#fullExecution');if(!target)return;if(job.status==='not_started'){target.innerHTML='<p><small>确认研究方案后，Agent 可以自动执行下方全部步骤。</small></p>';return}const icons={pending:'·',running:'✦',completed:'✓',failed:'!',cancelled:'×'},phases=(job.phases||[]).map(item=>`<div class="${['failed','cancelled'].includes(item.status)?'warning':'check'}"><b>${icons[item.status]||'·'}　${esc(item.label)}</b> · ${esc(item.status)}${item.summary?`<br><small>${esc(JSON.stringify(item.summary))}</small>`:''}</div>`).join('');const links=job.status==='completed'?`<p><a class="primary" href="/api/projects/${activeProject.id}/analysis-report" target="_blank" rel="noopener">查看结构化报告</a> <a href="/api/projects/${activeProject.id}/analysis-result-download">下载完整结果包</a></p>`:'';target.innerHTML=`${job.recovered?'<div class="check"><b>✓　服务器重启后已恢复此任务</b><br><small>任务状态已从 SQLite 恢复，Agent 会从安全检查点重新执行。</small></div>':''}${job.status==='cancelled'?'<div class="warning">任务已由研究者取消，可以重新执行。</div>':''}${job.error?`<div class="warning">${esc(job.error)}</div>`:''}${phases}${links}`}
async function pollFullExecution(transitionId,projectId=activeProject.id){for(let attempt=0;attempt<1200;attempt++){const response=await resilientFetch(`/api/projects/${projectId}/execute`,{},{onRetry:retry=>updateAgentTransition(transitionId,{description:`网络暂时中断，正在第 ${retry} 次重连…`})}),job=await response.json();if(activeProject?.id===projectId)renderFullExecution(job);const phases=job.phases||[],completed=phases.filter(item=>item.status==='completed').length,runningIndex=phases.findIndex(item=>item.status==='running'),index=runningIndex>=0?runningIndex:Math.min(completed,Math.max(0,phases.length-1)),current=phases[index];updateAgentTransition(transitionId,{index,progress:phases.length?completed/phases.length*100:5,description:current?`${current.label}，完成后将自动进入下一步`:'Agent 正在排队准备研究任务'});if(['completed','failed','cancelled','not_started'].includes(job.status))return job;await new Promise(resolve=>setTimeout(resolve,1000))}throw new Error('Agent 执行超时')}
async function trackFullExecution(job,button,resumed=false){const projectId=job.projectId||activeProject.id;if(fullExecutionWatcher===projectId)return;fullExecutionWatcher=projectId;if(button){button.disabled=true;button.textContent='Agent 执行中…'}const transitionId=beginAgentTransition({title:resumed?'已恢复正在运行的研究任务':'正在执行完整研究流程',description:resumed?'页面已重新连接，Agent 将继续显示实时进度':'Agent 正在准备经过审核的数据和模型',steps:['验证 CDC 数据','缓存 XPT 文件','执行 R 分析','质量检查与报告'],startedAt:job.startedAt,onCancel:async()=>{const response=await fetch(`/api/projects/${projectId}/execute`,{method:'DELETE'});if(!response.ok)throw new Error('服务器拒绝取消任务');updateAgentTransition(transitionId,{description:'取消请求已确认，正在安全停止当前步骤…'})}});try{const completed=await pollFullExecution(transitionId,projectId);if(completed.status==='cancelled'){endAgentTransition(transitionId,{success:false,cancelled:true,message:'当前研究任务已安全停止，可以稍后重新执行'});toast('研究任务已取消');return}if(completed.status!=='completed')throw new Error(completed.error||'完整研究流程未完成');const analysis=await resilientFetch(`/api/projects/${projectId}/analysis-run`).then(r=>r.json());if(activeProject?.id===projectId)renderAnalysisRun(analysis);endAgentTransition(transitionId,{message:'分析、质量检查和报告已全部完成'});toast('分析、质量检查和报告已全部完成')}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});if(activeProject?.id===projectId&&$('#fullExecution'))$('#fullExecution').innerHTML=`<div class="warning">${esc(error.message)}</div>`}finally{fullExecutionWatcher='';if(button&&document.body.contains(button)){button.disabled=false;button.textContent='✦ Agent 重新执行全流程'}}}
function bindFullExecution(){const button=$('#runFullExecution');if(!button)return;fetch(`/api/projects/${activeProject.id}/execute`).then(r=>r.json()).then(job=>{renderFullExecution(job);if(['queued','running'].includes(job.status))trackFullExecution(job,button,true)}).catch(()=>{});button.onclick=async()=>{button.disabled=true;button.textContent='Agent 执行中…';try{const response=await fetch(`/api/projects/${activeProject.id}/execute`,{method:'POST'}),job=await response.json();if(!response.ok)throw new Error(job.error?.message||'Agent 无法启动执行');renderFullExecution(job);await trackFullExecution(job,button)}catch(error){if(!activeTransition){const transitionId=beginAgentTransition({title:'Agent 无法启动',description:error.message,steps:['检查执行条件']});endAgentTransition(transitionId,{success:false,message:error.message})}if($('#fullExecution'))$('#fullExecution').innerHTML=`<div class="warning">${esc(error.message)}</div>`;button.disabled=false;button.textContent='✦ Agent 自动执行全流程'}}}
function bindDataValidation(){const button=$('#validateDataFiles');if(!button)return;button.onclick=async()=>{button.disabled=true;button.textContent='正在验证官方文件…';const transitionId=beginAgentTransition({title:'正在验证 CDC 数据文件',description:'Agent 正在检查下载地址、文件大小和 XPT 签名',steps:['生成清单','连接 CDC','验证文件签名','汇总结果']});try{updateAgentTransition(transitionId,{index:1,progress:24});const response=await fetch(`/api/projects/${activeProject.id}/data-manifest-validate`,{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.error?.message||'文件验证失败');updateAgentTransition(transitionId,{index:3,progress:92,description:`已验证 ${data.summary.valid}/${data.summary.total} 个 XPT 文件`});$('#dataValidation').innerHTML=`<div class="check"><b>${data.summary.invalid?'!':'✓'}　</b>已验证 ${esc(data.summary.valid)}/${esc(data.summary.total)} 个 XPT 文件；总大小约 ${(data.summary.totalBytes/1024/1024).toFixed(1)} MB。</div><table class="table"><thead><tr><th>周期</th><th>文件</th><th>签名</th><th>大小</th></tr></thead><tbody>${data.files.map(x=>`<tr><td>${esc(x.cycle)}</td><td><a href="${esc(x.documentationUrl)}" target="_blank" rel="noopener">${esc(x.code)}</a></td><td>${x.signatureValid?'有效':'失败'}</td><td>${(x.totalBytes/1024).toFixed(0)} KB</td></tr>`).join('')}</tbody></table>`;endAgentTransition(transitionId,{success:!data.summary.invalid,message:data.summary.invalid?`${data.summary.invalid} 个文件验证失败`:'CDC 官方文件验证完成'})}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});$('#dataValidation').innerHTML=`<div class="warning">${esc(error.message)}</div>`}finally{button.disabled=false;button.textContent='重新验证 CDC 官方 XPT 文件'}}}
function renderDataCache(job){const target=$('#dataCache');if(!target)return;const done=job.status==='completed',failed=['failed','cancelled'].includes(job.status);target.innerHTML=`<div class="${failed?'warning':'check'}"><b>${done?'✓':job.status==='cancelled'?'×':failed?'!':'↓'}　</b>数据缓存：${esc(job.status)} · ${esc(job.completedFiles)}/${esc(job.totalFiles)} 个文件${job.currentFile?` · 正在下载 ${esc(job.currentFile)}`:''}${job.bytesDownloaded?` · 本次 ${(job.bytesDownloaded/1024/1024).toFixed(1)} MB`:''}${job.error?`<br>${esc(job.error)}`:''}</div>`}
async function pollDataCache(transitionId,projectId=activeProject.id){for(let attempt=0;attempt<180;attempt++){const response=await resilientFetch(`/api/projects/${projectId}/data-cache`,{},{onRetry:retry=>updateAgentTransition(transitionId,{description:`网络暂时中断，正在第 ${retry} 次重连…`})}),job=await response.json();renderDataCache(job);const total=Number(job.totalFiles)||0,done=Number(job.completedFiles)||0;updateAgentTransition(transitionId,{index:job.status==='completed'?2:1,progress:total?Math.min(94,10+done/total*80):10,description:job.currentFile?`正在下载 ${job.currentFile}（${done}/${total}）`:`正在准备数据文件（${done}/${total||'—'}）`});if(['completed','failed','cancelled','not_started'].includes(job.status))return job;await new Promise(resolve=>setTimeout(resolve,1000))}throw new Error('数据缓存任务超时')}
function bindDataCache(){const button=$('#cacheDataFiles');if(!button)return;fetch(`/api/projects/${activeProject.id}/data-cache`).then(r=>r.json()).then(renderDataCache).catch(()=>{});button.onclick=async()=>{button.disabled=true;button.textContent='缓存任务运行中…';const projectId=activeProject.id,transitionId=beginAgentTransition({title:'正在缓存 NHANES 数据',description:'Agent 正在把经过验证的 XPT 文件下载到分析服务器',steps:['准备下载清单','下载与校验','完成服务器缓存'],onCancel:async()=>{const response=await fetch(`/api/projects/${projectId}/data-cache`,{method:'DELETE'});if(!response.ok)throw new Error('服务器拒绝取消缓存任务');updateAgentTransition(transitionId,{description:'正在安全停止数据下载…'})}});try{const response=await fetch(`/api/projects/${projectId}/data-cache`,{method:'POST'}),job=await response.json();if(!response.ok)throw new Error(job.error?.message||'缓存任务启动失败');renderDataCache(job);const completed=await pollDataCache(transitionId,projectId);if(completed.status==='cancelled'){endAgentTransition(transitionId,{success:false,cancelled:true,message:'数据缓存任务已安全停止'});return}if(completed.status!=='completed')throw new Error(completed.error||'数据缓存未完成');endAgentTransition(transitionId,{message:`数据缓存完成，共处理 ${completed.completedFiles||0} 个文件`})}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});$('#dataCache').innerHTML=`<div class="warning">${esc(error.message)}</div>`}finally{button.disabled=false;button.textContent='下载到服务器缓存'}}}
function renderAnalysisRun(job){const target=$('#analysisRun');if(!target)return;if(job.status==='not_started'){target.innerHTML='<div class="check">R 分析尚未执行。</div>';return}if(job.status==='failed'){target.innerHTML=`<div class="warning"><b>R 分析失败：</b> ${esc(job.error)}</div>`;return}if(job.status==='cancelled'){target.innerHTML='<div class="warning"><b>R 分析已取消。</b> 可以重新执行冻结的模型。</div>';return}if(job.status!=='completed'){target.innerHTML=`<div class="check"><b>R　</b>分析任务：${esc(job.status)}，请勿重复提交。</div>`;return}const result=job.result||{},quality=job.quality||{},flow=result.flow||{},coefficients=Array.isArray(result.coefficients)?result.coefficients:[],sensitivity=Array.isArray(result.sensitivityCoefficients)?result.sensitivityCoefficients:[],effect=x=>x.effect??x.odds_ratio,selected=sensitivity.filter(x=>(x.model==='vitamin_d_quartiles'&&String(x.term).includes('vitamin_quartile'))||(x.model==='continuous_phq9'&&x.term==='I(LBXVIDMS/10)')||(x.model==='sex_interaction'&&String(x.term).includes(':'))),publishable=quality.status==='passed',qc=`<div class="${publishable?'check':'warning'}"><b>${publishable?'✓':'!'}　结果质量门：${esc(quality.status||'待检查')}</b> · 通过 ${esc(quality.summary?.passed||0)}，失败 ${esc(quality.summary?.failed||0)}，警告 ${esc(quality.summary?.warnings||0)}</div>`,links=publishable?`<p><a class="primary" href="/api/projects/${activeProject.id}/analysis-report" target="_blank" rel="noopener">查看结构化报告</a> <a class="primary" href="/api/projects/${activeProject.id}/analysis-result-download">下载完整结果包</a> <a href="/api/projects/${activeProject.id}/analysis-quality" target="_blank" rel="noopener">查看 QC 明细</a></p>`:'<div class="warning">报告发布已阻止。请先修复失败的质量检查。</div>',table=`<h4>主模型</h4><table class="table"><thead><tr><th>变量</th><th>效应值</th><th>95% CI</th><th>P</th></tr></thead><tbody>${coefficients.map(x=>`<tr><td>${esc(x.term)}</td><td>${Number(effect(x)).toFixed(3)}</td><td>${Number(x.ci_low).toFixed(3)}–${Number(x.ci_high).toFixed(3)}</td><td>${Number(x.p_value).toPrecision(3)}</td></tr>`).join('')}</tbody></table>`;if(String(result.analysisMode||'').startsWith('generic_survey_v')){const sensitivityTable=sensitivity.length?`<h4>敏感性分析</h4><table class="table"><thead><tr><th>模型</th><th>效应值</th><th>95% CI</th><th>P</th></tr></thead><tbody>${sensitivity.map(x=>`<tr><td>${esc(x.model)}</td><td>${Number(effect(x)).toFixed(3)}</td><td>${Number(x.ci_low).toFixed(3)}–${Number(x.ci_high).toFixed(3)}</td><td>${Number(x.p_value).toPrecision(3)}</td></tr>`).join('')}</tbody></table>`:'';target.innerHTML=`<div class="check"><b>✓　</b>通用 R survey 分析已完成 · 完整案例 ${esc(flow.analytic_complete_case)} · 设计自由度 ${esc(result.designDiagnostics?.degreesFreedom??'—')} · ${esc(result.runtime?.rVersion||'R')}</div>${qc}${links}${table}${sensitivityTable}<small>${(result.warnings||[]).map(esc).join(' · ')}</small>`;return}target.innerHTML=`<div class="check"><b>✓　</b>真实 R 分析已完成 · 分析样本 ${esc(flow.analytic_complete_case)} · 抑郁病例 ${esc(flow.depression_cases)} · ${esc(result.runtime?.rVersion||'R')}</div>${qc}${links}${table}${selected.length?`<h4>敏感性分析关键项</h4><table class="table"><thead><tr><th>模型</th><th>变量</th><th>效应值</th><th>95% CI</th><th>P</th></tr></thead><tbody>${selected.map(x=>`<tr><td>${esc(x.model)}</td><td>${esc(x.term)}</td><td>${Number(effect(x)).toFixed(3)}</td><td>${Number(x.ci_low).toFixed(3)}–${Number(x.ci_high).toFixed(3)}</td><td>${Number(x.p_value).toPrecision(3)}</td></tr>`).join('')}</tbody></table>`:''}<small>${(result.warnings||[]).map(esc).join(' · ')}</small>`}
async function pollAnalysisRun(transitionId,projectId=activeProject.id){for(let attempt=0;attempt<600;attempt++){const response=await resilientFetch(`/api/projects/${projectId}/analysis-run`,{},{onRetry:retry=>updateAgentTransition(transitionId,{description:`网络暂时中断，正在第 ${retry} 次重连…`})}),job=await response.json();renderAnalysisRun(job);updateAgentTransition(transitionId,{index:job.status==='completed'?2:1,progress:job.status==='completed'?94:35,description:job.status==='completed'?'R survey 模型已完成，正在读取质量检查结果':'R survey 正在拟合模型并生成诊断'});if(['completed','failed','cancelled','not_started'].includes(job.status))return job;await new Promise(resolve=>setTimeout(resolve,1000))}throw new Error('R 分析任务超时')}
function bindAnalysisRun(){const button=$('#runRAnalysis');if(!button)return;fetch(`/api/projects/${activeProject.id}/analysis-run`).then(r=>r.json()).then(renderAnalysisRun).catch(()=>{});button.onclick=async()=>{button.disabled=true;button.textContent='R 分析运行中…';const projectId=activeProject.id,transitionId=beginAgentTransition({title:'正在执行 R survey 分析',description:'Agent 正在受控环境中运行冻结的统计模型',steps:['加载分析数据','拟合复杂抽样模型','质量检查与结果整理'],onCancel:async()=>{const response=await fetch(`/api/projects/${projectId}/analysis-run`,{method:'DELETE'});if(!response.ok)throw new Error('服务器拒绝取消分析任务');updateAgentTransition(transitionId,{description:'正在安全停止 R 进程…'})}});try{const response=await fetch(`/api/projects/${projectId}/analysis-run`,{method:'POST'}),job=await response.json();if(!response.ok)throw new Error(job.error?.message||'R 分析无法启动');renderAnalysisRun(job);const completed=await pollAnalysisRun(transitionId,projectId);if(completed.status==='cancelled'){endAgentTransition(transitionId,{success:false,cancelled:true,message:'R 分析任务已安全停止'});return}if(completed.status!=='completed')throw new Error(completed.error||'R 分析未完成');endAgentTransition(transitionId,{message:'R survey 分析与质量检查已完成'})}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});$('#analysisRun').innerHTML=`<div class="warning">${esc(error.message)}</div>`}finally{button.disabled=false;button.textContent='执行受控 R 分析'}}}
$('#run').onclick=async()=>{if(!$('#question').value)$('#question').value=$$('[data-example]')[0].dataset.example;const transitionId=beginAgentTransition({title:'正在理解您的研究问题',description:'Agent 将依次完成解析、变量匹配、文献检索和方案设计',steps:['问题解析','变量匹配','文献检索','方案生成']});try{const response=await fetch('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:$('#question').value})});const payload=await response.json();if(!response.ok)throw new Error(payload.error?.message||'创建项目失败');syncProject(payload);$('#start').classList.add('hidden');$('#results').classList.remove('hidden');window.scrollTo(0,0);eventSource=new EventSource(`/api/projects/${activeProject.id}/events`);eventSource.onmessage=async e=>{const event=JSON.parse(e.data),stageNames={parse:'正在识别暴露、结局、目标人群和周期',variables:'正在匹配 NHANES 数据集和变量',literature:'正在检索并整理 PubMed 文献',protocol:'正在结合证据生成统计分析方案'},index=['parse','variables','literature','protocol','analysis','quality','report'].indexOf(event.stage);if(index>=0){pipeline(Math.min(index,5));updateAgentTransition(transitionId,{index:Math.min(index,3),progress:Math.min(92,(index+1)*23),description:stageNames[event.stage]||event.message})}if(event.status==='blocked'){const latest=await fetch(`/api/projects/${activeProject.id}`).then(r=>r.json());syncProject(latest);endAgentTransition(transitionId,{message:'研究方案已经生成，等待您确认'});toast('方案已生成，等待研究者确认');eventSource.close()}};const started=await fetch(`/api/projects/${activeProject.id}/run`,{method:'POST'});if(!started.ok)throw new Error('Agent 启动失败')}catch(error){endAgentTransition(transitionId,{success:false,message:error.message});toast(error.message)}};
$('#newStudy').onclick=()=>{eventSource?.close();activeProject=null;$('#headerProjectTitle').textContent='未命名研究';$('#results').classList.add('hidden');$('#start').classList.remove('hidden');$('#question').value='';$$('.recent-project').forEach(x=>x.classList.remove('selected'))};
const approvalDialog=$('#approvalDialog');
$('#continue').onclick=()=>{if(!activeProject||activeProject.status!=='awaiting_approval'){toast('请等待方案生成完成');return}approvalDialog.showModal()};
$('#cancelApproval').onclick=$('#cancelApprovalBottom').onclick=()=>approvalDialog.close();
$('#approvalForm').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;try{const decisions={outcome_definition:$('#approvalOutcome').value,exposure_parameterization:$('#approvalExposure').value,covariate_set:$('#approvalCovariates').value,missing_data:$('#approvalMissing').value,association_only:$('#approvalAssociation').checked},response=await fetch(`/api/projects/${activeProject.id}/approve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:'researcher',decisions})}),project=await response.json();if(!response.ok)throw new Error(project.error?.message||'方案确认失败');approvalDialog.close();syncProject(project);await loadRecentProjects();toast('研究方案已确认、冻结并写入审计记录')}catch(error){toast(error.message)}finally{submit.disabled=false}};
$('#export').onclick=()=>{const cycles=(activeProject?.intent?.cycles||[]).join('、')||'待确认',approval=activeProject?.approvals?.at(-1),decisionLines=approval?Object.entries(approval.decisions).map(([key,value])=>`- ${key}：${value}`).join('\n'):'- 尚未确认',b=new Blob([`# ${activeProject?.title||'NHANES 研究方案'}\n\n- 原始问题：${activeProject?.question||''}\n- 周期：${cycles}\n- 设计：复杂抽样加权横断面研究\n\n## 冻结决策\n\n${decisionLines}\n`],{type:'text/markdown'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='nhanes-study-protocol.md';a.click();toast('方案已导出')};pipeline();logs();tab('design');loadRecentProjects();
